def non_divisible_subset(k: int, s: list[int]) -> int:
    rems = [0] * k
    for x in s:
        rems[x % k] += 1
    count = min(1, rems[0])
    for i in range(1, (k // 2) + 1):
        if i != k - i:
            count += max(rems[i], rems[k - i])
        else:
            count += min(1, rems[i])
    return count
